// Using a Fragment
function AppWithFragment() {
  return (
    <>
      <h1>Hello</h1>
      <p>Welcome</p>
    </>
  );
}

function App() {
  const name = "Jeet";
  const age = 22;

  return (
    <div>
      <h1>Hello, {name}</h1>
      <p>Next year: {age + 1}</p>
    </div>
  );
}

function App({ isLoggedIn }) {
  if (isLoggedIn) {
    return <h1>Welcome back!</h1>;
  } else {
    return <h1>Please log in.</h1>;
  }
}

// Or use a ternary expression inside JSX.

function App({ isLoggedIn, hasNotification }) {
  return (
    <div>
      {isLoggedIn ? (
        <h1>Welcome!</h1>
      ) : (
        <button>Login</button>
      )}

      {hasNotification && <p>New notification!</p>}
    </div>
  );
}

function App() {
  const name = "Jeet";

  return (
    <div>
      {/* Curly braces evaluate JavaScript expressions */}
      <h1>Hello, {name}</h1>

      {/* Parentheses group multi-line JSX */}
      {true && (
        <p>This is visible</p>
      )}
    </div>
  );
}

